var Packs_DeletePackSchemaJSON = `{"description":"Deletes a pack. DELETE /v1/{name=packs/*} Soft delete: the pack is marked deleted, disappears from List unless ` + "`" + `show_deleted` + "`" + ` is set, and is purged at ` + "`" + `expire_time` + "`" + `. Recover it with Undelete before then. Idempotent in effect but not in reporting: a second delete returns NOT_FOUND rather than succeeding silently. NOT_FOUND          no such pack ABORTED            etag does not match PERMISSION_DENIED  caller may not delete it","properties":{"name":{"description":"Name of the pack to delete, \"packs/{pack}\".","pattern":"^packs/[^/]+$","type":"string"}},"required":["name"],"type":"object"}`
