var Packs_ListPacksSchemaJSON = `{"description":"Lists packs. GET /v1/packs Paginated per AIP-158: pass ` + "`" + `page_size` + "`" + ` (defaults to 50, capped at 1000) and the ` + "`" + `next_page_token` + "`" + ` from the previous response. An empty ` + "`" + `next_page_token` + "`" + ` means the last page. Page tokens are opaque and may expire; do not construct or store them. Filtering uses the AIP-160 expression language over the pack's own fields. ` + "`" + `resolved = true` + "`" + ` is the query an archive wants, since section 4.6 \u003chttps://www.rfc-editor.org/rfc/rfc8428.html#section-4.6\u003e's normalised form is what bulk processing consumes. Filtering by sensor means matching the name strings inside ` + "`" + `records` + "`" + `, which a filter cannot see into -- resolve first, or keep an index outside this API. Results carry no guaranteed order. INVALID_ARGUMENT   malformed filter, or page_size out of range PERMISSION_DENIED  caller may not list this collection","properties":{"filter":{"description":"Filter expression, AIP-160 \u003chttps://aip.dev/160\u003e.","type":"string"},"page_size":{"description":"Maximum packs to return. Defaults to 50, capped at 1000.","maximum":1000,"minimum":0,"type":"integer"},"page_token":{"description":"Page token from a previous ListPacksResponse.next_page_token.","type":"string"},"show_deleted":{"description":"Include soft-deleted packs in the result. AIP-164 \u003chttps://aip.dev/164\u003e.","type":"boolean"}},"required":[],"type":"object"}`
var Packs_ResolvePackSchemaJSON = `{"description":"Normalises a pack into resolved records, RFC 8428 section 4.6 \u003chttps://www.rfc-editor.org/rfc/rfc8428.html#section-4.6\u003e. POST /v1/{name=packs/*}:resolve body: the whole request message A custom method (AIP-136) rather than a ` + "`" + `shared/v1` + "`" + ` capability, because resolution is not cross-cutting the way export and search are: it is defined by section 4.6 \u003chttps://www.rfc-editor.org/rfc/rfc8428.html#section-4.6\u003e for this format alone, and no other resource in this schema has base fields to fold away. That is rule 7's test, and the same one ExpandEvent passes for recurrence rules. Concatenates each name onto the base name in force, adds base times to times, applies base units and base values, converts relative times against ` + "`" + `reference_time_value` + "`" + `, and returns the records in chronological order. Nothing is written: the stored pack is untouched and ` + "`" + `resolved` + "`" + ` stays as it was. Resolved records are also the only form in which a record may leave its pack, since an unresolved one means nothing on its own. Safe and idempotent given the same ` + "`" + `reference_time_value` + "`" + `. Without one the server reads its own clock, so two calls on a pack holding relative times return different absolute times -- supply the reference when that matters. NOT_FOUND          no such pack INVALID_ARGUMENT   a record's base and regular time sum past 2**28 and flips a relative time absolute PERMISSION_DENIED  caller may not read it","properties":{"name":{"description":"Name of the pack to resolve, \"packs/{pack}\".","pattern":"^packs/[^/]+$","type":"string"},"reference_time_value":{"description":"The instant to read relative times against, as POSIX seconds since the Unix epoch, RFC 8428 section 4.5.3 \u003chttps://www.rfc-editor.org/rfc/rfc8428.html#section-4.5.3\u003e. The server uses its own clock when unset. A caller supplies this when it, not the server, knows what \"now\" meant for this pack -- a batch of readings buffered on a gateway for an hour resolves against the time they were *taken*, not the time they were uploaded, and the server has no way to tell the difference. Section 4.5.3 \u003chttps://www.rfc-editor.org/rfc/rfc8428.html#section-4.5.3\u003e leaves the accuracy of \"now\" to the surrounding system for exactly this reason, so the schema takes it as input rather than guessing. Named ` + "`" + `_value` + "`" + ` and typed double for the reason given on ` + "`" + `Record.time_value` + "`" + `: it is the same quantity on the same scale, and a Timestamp here would silently disagree with the field it is being added to. Ignored when the pack has no relative time.","type":"number"}},"required":["name"],"type":"object"}`
var Packs_UndeletePackSchemaJSON = `{"description":"Restores a soft-deleted pack. POST /v1/{name=packs/*}:undelete Valid only before ` + "`" + `expire_time` + "`" + `; after that the pack is gone and this returns NOT_FOUND. Clears ` + "`" + `delete_time` + "`" + ` and ` + "`" + `expire_time` + "`" + ` and returns the pack as it was. NOT_FOUND          no such pack, or already purged ALREADY_EXISTS     the pack is not deleted PERMISSION_DENIED  caller may not restore it","properties":{"name":{"description":"Name of the soft-deleted pack to restore.","pattern":"^packs/[^/]+$","type":"string"}},"required":["name"],"type":"object"}`
var Packs_UpdatePackSchemaJSON = `{"description":"Updates a pack. PATCH /v1/{pack.name=packs/*} body: the pack itself A partial update: only fields named in ` + "`" + `update_mask` + "`" + ` are written. An empty mask writes every mutable field, which will clear anything the caller left unset -- pass a mask unless that is the intent. OUTPUT_ONLY and IMMUTABLE fields are rejected rather than silently dropped. ` + "`" + `records` + "`" + ` replaces wholesale when masked; there is no append. A record's base fields govern the records after it (section 4.1 \u003chttps://www.rfc-editor.org/rfc/rfc8428.html#section-4.1\u003e), so merging a partial list into a stored one would change the meaning of records the caller never sent. Idempotent. Pass the ` + "`" + `etag` + "`" + ` read from Get to make the write conditional. NOT_FOUND          no such pack ABORTED            etag does not match the stored pack INVALID_ARGUMENT   mask names an unknown or immutable field PERMISSION_DENIED  caller may not modify it","properties":{"pack":{"description":"The pack to update. Its name field identifies the pack.","properties":{"base_version":{"anyOf":[{"const":0},{"minimum":10}],"description":"Base Version (bver), RFC 8428 section 4.1 \u003chttps://www.rfc-editor.org/rfc/rfc8428.html#section-4.1\u003e. Defaults to 10 when unset. On the Pack rather than on ` + "`" + `Record` + "`" + `, where the wire format puts it, because section 4.4 \u003chttps://www.rfc-editor.org/rfc/rfc8428.html#section-4.4\u003e requires every record in a Pack to carry the same version and expects a producer to write it onto the first record only. Hoisting it is lossless in both directions and removes the one place the records could contradict each other. A serialiser writing resolved records puts it back on each of them, per section 4.6 \u003chttps://www.rfc-editor.org/rfc/rfc8428.html#section-4.6\u003e. Not a linear version. RFC 9100 \u003chttps://www.rfc-editor.org/rfc/rfc9100.html\u003e reinterprets the number as a bitmap of feature codes -- bit ` + "`" + `c` + "`" + ` set means feature ` + "`" + `c` + "`" + ` is in use -- so 10 is 0b1010, the four reserved codes of the base specification, and 26 is that plus RFC 8798 \u003chttps://www.rfc-editor.org/rfc/rfc8798.html\u003e's secondary units at code 4. A reader must therefore compare bitwise and reject a pack asserting any bit it does not implement, not compare magnitudes: RFC 9100 section 2.2 \u003chttps://www.rfc-editor.org/rfc/rfc9100.html#section-2.2\u003e gives the case where an implementation accepts 42 and rejects 26. The floor of 10 follows from that bitmap: RFC 9100 section 3 \u003chttps://www.rfc-editor.org/rfc/rfc9100.html#section-3\u003e makes codes 1 and 3 always present, so every legal version has both bits set. int32, not uint32, per AIP-141 \u003chttps://aip.dev/141\u003e.","type":"integer"},"name":{"anyOf":[{"const":""},{"pattern":"^packs/[^/]+$"}],"description":"Resource name, \"packs/{pack}\".","type":"string"},"records":{"items":{"anyOf":[{"$comment":"Protobuf oneOf group.","oneOf":[{"properties":{"number_value":{"description":"Value (v), section 4.2 \u003chttps://www.rfc-editor.org/rfc/rfc8428.html#section-4.2\u003e. Added to the ` + "`" + `base_value` + "`" + ` in force.","type":"number"}},"required":["number_value"]},{"properties":{"string_value":{"description":"String Value (vs), section 4.2 \u003chttps://www.rfc-editor.org/rfc/rfc8428.html#section-4.2\u003e, e.g. \"Machine Room\".","type":"string"}},"required":["string_value"]},{"properties":{"boolean_value":{"description":"Boolean Value (vb), section 4.2 \u003chttps://www.rfc-editor.org/rfc/rfc8428.html#section-4.2\u003e.","type":"boolean"}},"required":["boolean_value"]},{"properties":{"data_value":{"contentEncoding":"base64","description":"Data Value (vd), section 4.2 \u003chttps://www.rfc-editor.org/rfc/rfc8428.html#section-4.2\u003e. Arbitrary octets. Held decoded. Section 4.3 \u003chttps://www.rfc-editor.org/rfc/rfc8428.html#section-4.3\u003e carries this base64url-encoded without padding in JSON and XML and as a definite-length byte string in CBOR; a protobuf ` + "`" + `bytes` + "`" + ` field is already binary, so re-encoding it would store one of those two spellings and make the other lossy. Same treatment ` + "`" + `StructuredData.binary` + "`" + ` gives ENCODING=BASE64 in rfc9073.","format":"byte","type":"string"}},"required":["data_value"]}]}],"description":"The records, in order, section 4 \u003chttps://www.rfc-editor.org/rfc/rfc8428.html#section-4\u003e. Order is load-bearing twice over: a base field applies to the records *following* the one it appears in (section 4.1 \u003chttps://www.rfc-editor.org/rfc/rfc8428.html#section-4.1\u003e), and a resolved pack must additionally be in chronological order (section 4.6 \u003chttps://www.rfc-editor.org/rfc/rfc8428.html#section-4.6\u003e). Reordering this list changes what the pack means. At least one, from section 11 \u003chttps://www.rfc-editor.org/rfc/rfc8428.html#section-11\u003e's CDDL: ` + "`" + `SenML-Pack = [1* record]` + "`" + `.","properties":{"base_sensor_id":{"anyOf":[{"const":""},{"pattern":"^[A-Za-z0-9][-:./_A-Za-z0-9]*$"}],"description":"Base Name (bn), section 4.1 \u003chttps://www.rfc-editor.org/rfc/rfc8428.html#section-4.1\u003e. Prepended to ` + "`" + `sensor_id` + "`" + ` in this and every following record, e.g. \"urn:dev:ow:10e2073a01080063:\". Named base_sensor_id, not base_name: AIP-122 \u003chttps://aip.dev/122\u003e bans the ` + "`" + `_name` + "`" + ` suffix on everything but display_name, given_name and family_name. ` + "`" + `id` + "`" + ` rather than ` + "`" + `identifier` + "`" + ` is AIP-140 \u003chttps://aip.dev/140\u003e, and section 4.5.1 \u003chttps://www.rfc-editor.org/rfc/rfc8428.html#section-4.5.1\u003e is explicit that the concatenation \"must result in a globally unique identifier\". The character set is section 4.5.1 \u003chttps://www.rfc-editor.org/rfc/rfc8428.html#section-4.5.1\u003e's, which constrains the *concatenated* name: it must start with an alphanumeric and continue with \"-\", \":\", \".\", \"/\" and \"_\". Only the leading record of a run can be checked for that first character, so the rule is enforced here, on the field that begins the concatenation, and documented on ` + "`" + `sensor_id` + "`" + `, which cannot see whether a base name precedes it.","type":"string"},"base_sum":{"description":"Base Sum (bs), section 4.1 \u003chttps://www.rfc-editor.org/rfc/rfc8428.html#section-4.1\u003e. Added to ` + "`" + `sum` + "`" + ` in this and every following record. Explicitly optional, unlike ` + "`" + `base_value` + "`" + ` above, because section 4.5.4 \u003chttps://www.rfc-editor.org/rfc/rfc8428.html#section-4.5.4\u003e treats absence and zero differently here: a missing Base Sum next to a present Sum counts as zero, but a record with *neither* has no sum at all, and that is what decides whether section 4.2 \u003chttps://www.rfc-editor.org/rfc/rfc8428.html#section-4.2\u003e still demands a value.","type":"number"},"base_time_value":{"description":"Base Time (bt), section 4.1 \u003chttps://www.rfc-editor.org/rfc/rfc8428.html#section-4.1\u003e. Added to ` + "`" + `time_value` + "`" + ` in this and every following record. Seconds, with the two-regime reading described on ` + "`" + `time_value` + "`" + `. Named base_time_value, not base_time: AIP-142 \u003chttps://aip.dev/142\u003e requires a ` + "`" + `_time` + "`" + ` field to be a google.protobuf.Timestamp, and this is a double that is only sometimes an absolute instant. The ` + "`" + `_value` + "`" + ` escape is the one ` + "`" + `date_value` + "`" + ` already took in rfc9553/card.","type":"number"},"base_unit":{"description":"Base Unit (bu), section 4.1 \u003chttps://www.rfc-editor.org/rfc/rfc8428.html#section-4.1\u003e. The unit assumed for this and every following record that carries no ` + "`" + `unit` + "`" + ` of its own, section 4.5.2 \u003chttps://www.rfc-editor.org/rfc/rfc8428.html#section-4.5.2\u003e.","type":"string"},"base_value":{"description":"Base Value (bv), section 4.1 \u003chttps://www.rfc-editor.org/rfc/rfc8428.html#section-4.1\u003e. Added to ` + "`" + `number_value` + "`" + ` in this and every following record. Absent is zero, section 4.5.4 \u003chttps://www.rfc-editor.org/rfc/rfc8428.html#section-4.5.4\u003e, so no explicit presence is needed here.","type":"number"},"extensions":{"items":{"anyOf":[{"$comment":"Protobuf oneOf group.","oneOf":[{"properties":{"string_value":{"description":"A text value.","type":"string"}},"required":["string_value"]},{"properties":{"number_value":{"description":"A numeric value.","type":"number"}},"required":["number_value"]},{"properties":{"boolean_value":{"description":"A boolean value.","type":"boolean"}},"required":["boolean_value"]},{"properties":{"data_value":{"contentEncoding":"base64","description":"Binary data, held decoded for the reason given on ` + "`" + `Record.data_value` + "`" + `.","format":"byte","type":"string"}},"required":["data_value"]}]}],"description":"Fields this schema does not model, section 4.4 \u003chttps://www.rfc-editor.org/rfc/rfc8428.html#section-4.4\u003e. SenML is extensible by design and section 4.4 \u003chttps://www.rfc-editor.org/rfc/rfc8428.html#section-4.4\u003e *requires* a reader to ignore labels it does not recognise, so dropping them is non-conforming rather than merely lossy. Anything registered in the \"SenML Labels\" registry after this schema shipped arrives here and round-trips intact.","properties":{"label":{"description":"The SenML Label, section 12.2 \u003chttps://www.rfc-editor.org/rfc/rfc8428.html#section-12.2\u003e, e.g. \"bver_\" or \"myfield\". Not called ` + "`" + `name` + "`" + `, which would make api-linter treat this message as a resource -- the same rename ` + "`" + `ExtensionProperty.key` + "`" + ` took in rfc5545. The pattern is section 11 \u003chttps://www.rfc-editor.org/rfc/rfc8428.html#section-11\u003e's CDDL, both alternatives: a base label is \"b\" followed by one or more of the allowed characters, and a regular label starts with any alphanumeric *except* lower-case \"b\", which is what keeps the two apart.","pattern":"^(b[-_:.A-Za-z0-9]+|[A-Zac-z0-9][-_:.A-Za-z0-9]*)$","type":"string"}},"required":["label"],"type":"object"},"type":"array"},"sensor_id":{"anyOf":[{"const":""},{"pattern":"^[-:./_A-Za-z0-9]*$"}],"description":"Name (n), section 4.2 \u003chttps://www.rfc-editor.org/rfc/rfc8428.html#section-4.2\u003e. Appended to the ` + "`" + `base_sensor_id` + "`" + ` in force, e.g. \"voltage\". Section 4.2 \u003chttps://www.rfc-editor.org/rfc/rfc8428.html#section-4.2\u003e permits this to name a parameter or an actuator as well as a sensor; section 4.9 \u003chttps://www.rfc-editor.org/rfc/rfc8428.html#section-4.9\u003e is the actuation case. Named sensor_id, not name: a field called ` + "`" + `name` + "`" + ` makes api-linter treat the enclosing message as a resource, which ` + "`" + `Record` + "`" + ` is not -- the same rename vCard's N took to ` + "`" + `name_components` + "`" + `. The pattern here is section 4.5.1 \u003chttps://www.rfc-editor.org/rfc/rfc8428.html#section-4.5.1\u003e's continuation set, without the leading-alphanumeric rule: this field is usually a suffix, so \"voltage\" and \":current\" are both legal halves of a legal whole. When no base name is in force it carries the whole name and must satisfy the leading rule too, which no per-field constraint can see -- a codec checks the concatenation.","type":"string"},"sum":{"description":"Sum (s), section 4.2 \u003chttps://www.rfc-editor.org/rfc/rfc8428.html#section-4.2\u003e. The integrated sum of the values over time, in ` + "`" + `unit` + "`" + ` multiplied by seconds. Named \"sum\" rather than \"integral\" for historical reasons, which section 4.2 \u003chttps://www.rfc-editor.org/rfc/rfc8428.html#section-4.2\u003e notes itself. Explicitly optional for the reason given on ` + "`" + `base_sum` + "`" + `.","type":"number"},"time_value":{"description":"Time (t), section 4.2 \u003chttps://www.rfc-editor.org/rfc/rfc8428.html#section-4.2\u003e. When the value was recorded, added to the ` + "`" + `base_time_value` + "`" + ` in force. Seconds, and read two ways depending on magnitude, section 4.5.3 \u003chttps://www.rfc-editor.org/rfc/rfc8428.html#section-4.5.3\u003e: below 2**28 (268435456) it is relative to \"now\" -- zero meaning the sensor has no clock and the reading is roughly now, negative meaning seconds ago -- and at or above 2**28 it is absolute POSIX seconds since the Unix epoch, so the smallest absolute value expressible is 1978-07-04T21:24:16Z. Because base and regular are summed, a pair of relative values can drift over 2**28 and silently become absolute; section 4.5.3 \u003chttps://www.rfc-editor.org/rfc/rfc8428.html#section-4.5.3\u003e warns about exactly that. Not a google.protobuf.Timestamp, and named ` + "`" + `_value` + "`" + ` rather than ` + "`" + `_time` + "`" + ` to keep AIP-142 \u003chttps://aip.dev/142\u003e from demanding one: a relative time has no instant to put in a Timestamp until a reader supplies \"now\", and section 4.5.3 \u003chttps://www.rfc-editor.org/rfc/rfc8428.html#section-4.5.3\u003e leaves the accuracy of \"now\" to the surrounding system. Resolving to absolute time is ` + "`" + `Packs.ResolvePack` + "`" + `'s job, and section 4.5.3 \u003chttps://www.rfc-editor.org/rfc/rfc8428.html#section-4.5.3\u003e expects it to happen before anything is archived.","type":"number"},"unit":{"description":"Unit (u), section 4.2 \u003chttps://www.rfc-editor.org/rfc/rfc8428.html#section-4.2\u003e, e.g. \"Cel\", \"%RH\", \"V\". Falls back to the ` + "`" + `base_unit` + "`" + ` in force when unset, section 4.5.2 \u003chttps://www.rfc-editor.org/rfc/rfc8428.html#section-4.5.2\u003e; having neither is allowed and leaves the unit to the application. Free text, not an enum. Section 12.1 \u003chttps://www.rfc-editor.org/rfc/rfc8428.html#section-12.1\u003e points at the IANA \"SenML Units\" registry, which RFC 8798 \u003chttps://www.rfc-editor.org/rfc/rfc8798.html\u003e has already extended and which grows by expert review, so a closed list here would reject units registered after this schema shipped. Same call ` + "`" + `Resource.resource_types` + "`" + ` made in rfc9073.","type":"string"},"update_duration":{"description":"Update Time (ut), section 4.2 \u003chttps://www.rfc-editor.org/rfc/rfc8428.html#section-4.2\u003e. The longest a consumer should wait before this sensor provides a fresh reading; a longer silence means the sensor or the path to it has failed. A google.protobuf.Duration, where every other time-ish field here is a double: section 4.2 \u003chttps://www.rfc-editor.org/rfc/rfc8428.html#section-4.2\u003e defines this one as a period of seconds outright, with none of ` + "`" + `time_value` + "`" + `'s relative-or-absolute ambiguity, and AIP-142 \u003chttps://aip.dev/142\u003e requires a ` + "`" + `_duration` + "`" + ` field to be a Duration.","pattern":"^-?[0-9]+(\\.[0-9]+)?s$","type":["string","null"]}},"required":[],"type":"object"},"minItems":1,"type":"array"}},"required":["records"],"type":"object"},"update_mask":{"description":"Fields to update. An empty mask updates all mutable fields.","type":"string"}},"required":["pack"],"type":"object"}`

